import java.io.*;
import java.util.*;

public class OneBasedArithmetic {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        long n = Long.parseLong(br.readLine().trim());
        long[] ones = new long[17];
        for (int i = 1; i < 17; i++) {
            ones[i] = ones[i-1] * 10 + 1;
        }
        long result = calculate(ones, n, 16);
        System.out.println(result);
    }

    private static long calculate(long[] ones, long num, int level) {
        long unit = ones[level];
        long times = num / unit;
        long leftover = num % unit;
        long steps = times * level;
        if (leftover == 0) {
            return steps;
        }
        long pathA = steps + calculate(ones, leftover, level - 1);
        long pathB = steps + level + calculate(ones, unit - leftover, level - 1);
        return Math.min(pathA, pathB);
    }

    private static class FastReader {
        private final BufferedReader br;
        private String[] tokens;
        private int tokenIndex;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
            tokens = new String[0];
            tokenIndex = 0;
        }

        private String fetchToken() throws IOException {
            while (tokenIndex >= tokens.length) {
                tokens = br.readLine().split("\\s+");
                tokenIndex = 0;
            }
            return tokens[tokenIndex++];
        }

        public String next() {
            try {
                return fetchToken();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
    }
}
